static NodeBase* erase_range_model(NodeBase* first, NodeBase* last)
{
    while (first != last) {
        NodeBase* n = first;
        first = first->_M_next;
        NodeBase* next_node = n->_M_next;
        NodeBase* prev_node = n->_M_prev;
        prev_node->_M_next = next_node;
        next_node->_M_prev = prev_node;
        std::free(n);
        ++g_freed;
    }
    return last;
}

