static void insert_before(NodeBase* n, long x)
{
    LongNode* tmp = (LongNode*)std::malloc(sizeof(LongNode));
    tmp->_M_data = x;
    NodeBase* p = n->_M_prev;
    tmp->_M_next = n;
    tmp->_M_prev = p;
    p->_M_next = tmp;
    n->_M_prev = tmp;
